<?php
declare(strict_types=1);
function fail(string $message): never { fwrite(STDERR, $message . PHP_EOL); exit(1); }
$repoRoot = dirname(__DIR__, 2);
require_once $repoRoot . '/master/src/Support/LeigodActivationGateContext.php';
require_once $repoRoot . '/master/src/Support/LeigodStandaloneBondActivationGateService.php';
function h(string $c): string { return str_repeat($c,64); }
function pins(): array { return ['client_agent'=>h('1'),'bond_binary'=>h('2')]; }
function runtime(): array { return ['backend_mode'=>'leigod_mode','client_mode'=>'bond','runtime_preference'=>'single','bond_ingress_mode'=>'plain_tcp_mux','active_family'=>'standalone_bond']; }
function leg(int $n): array { return ['forward_id'=>80,'desired_generation'=>5,'node_id'=>$n,'endpoint_id'=>100+$n,'protocol'=>'tcp','logical_leg_key'=>'bond:80:tcp:' . $n . ':' . (100+$n),'status'=>'active']; }
final class SrDb { public array $calls=[],$lifecycle=[],$cap=[],$proof=[],$rej=[]; public function fetchAll(string $sql,array $params=[]): array { $this->calls[]=['fetchAll',$sql,$params]; if(str_contains($sql,'lifecycle'))return $this->lifecycle; if(str_contains($sql,'capability'))return $this->cap; if(str_contains($sql,'rejections'))return array_values(array_filter($this->rej,fn($r)=>($r['scope']??'')===($params['scope']??'')&&($r['forward_id']??0)===($params['forward_id']??0)&&($r['assignment_hash']??'')===($params['assignment_hash']??''))); if(str_contains($sql,'activation_proofs'))return array_values(array_filter($this->proof,fn($r)=>($r['direction']??'')===($params['direction']??''))); return []; } public function fetchOne(string $sql,array $params=[]): ?array { $r=$this->fetchAll($sql,$params); return $r[0]??null; } }
final class SrAssign { public function __construct(public array $current, public array $legs){} public function loadCurrent(int $f, ?int $c, ?int $d, string $s='global'): ?array { return $this->current; } public function desiredLegRows(int $f, ?int $c, ?int $d, string $s='global'): array { return $this->legs; } }
final class SrArtifact { public function evaluate(array $scope): array { return ['ok'=>true]; } }
final class SrLock { public function requireHeld(string $s,string $k,string $o,string $f): void {} }
function ctx(string $legHash): \Leikwan\Master\Support\LeigodActivationGateContext { return \Leikwan\Master\Support\LeigodActivationGateContext::fromArray(['scope'=>'global','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'desired_generation'=>5,'assignment_id'=>888,'assignment_hash'=>h('a'),'desired_leg_set_hash'=>$legHash,'platform_family'=>'linux','write_mode'=>'activation','flags'=>['activation_enabled'=>true],'settings'=>['allowlisted_forward_ids'=>[80],'allowlisted_client_ids'=>[25],'allowlisted_device_session_ids'=>[35],'upload_min_mbps'=>10,'download_min_mbps'=>10],'expected_artifact_pins'=>pins(),'owner_token'=>h('c'),'fencing_token'=>h('d')]); }
function db(string $legHash): SrDb { $db=new SrDb(); $db->lifecycle[]=['scope'=>'global','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'desired_generation'=>5,'assignment_hash'=>h('a'),'desired_leg_set_hash'=>$legHash,'platform_family'=>'linux','snapshot_state'=>'accepted','created_at_unix'=>999]; $db->cap[]=['scope'=>'global','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'assignment_id'=>888,'desired_generation'=>5,'assignment_hash'=>h('a'),'platform_family'=>'linux','report_state'=>'accepted','proof_source'=>'client','created_at_unix'=>999,'artifact_hashes_json'=>json_encode(pins())]; foreach(['upload','download'] as $dir) $db->proof[]=['scope'=>'global','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'assignment_id'=>888,'desired_generation'=>5,'assignment_hash'=>h('a'),'platform_family'=>'linux','direction'=>$dir,'proof_state'=>'accepted','proof_source'=>'client_runtime_telemetry','created_at_unix'=>999,'mbps'=>50]; return $db; }
function runCase(SrDb $db,array $current,array $legs,string $legHash): array { return (new \Leikwan\Master\Support\LeigodStandaloneBondActivationGateService($db,new SrAssign($current,$legs),new SrArtifact(),new SrLock(),1000))->gate(ctx($legHash)); }
$legs=[leg(1),leg(2)]; $legHash=\Leikwan\Master\Support\StandaloneBondLegPolicy::canonicalLegSetHash(80,5,$legs); $current=['id'=>888,'forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'desired_generation'=>5,'assignment_hash'=>h('a'),'desired_leg_set_hash'=>$legHash,'platform_family'=>'linux','active_family'=>'standalone_bond','runtime_contract_json'=>json_encode(runtime())];
$r=runCase(db($legHash),$current,$legs,$legHash); if(!($r['ok']??false)) fail('baseline should pass: '.json_encode($r));
$empty=db($legHash); $empty->lifecycle=[]; $r=runCase($empty,$current,$legs,$legHash); if(!in_array('lifecycle_snapshot_missing',$r['blockers']??[],true)) fail('missing lifecycle expected: '.json_encode($r));
$stale=db($legHash); $stale->lifecycle[0]['created_at_unix']=985; $r=runCase($stale,$current,$legs,$legHash); if(!in_array('lifecycle_snapshot_stale',$r['blockers']??[],true)) fail('exactly 15s old snapshot must be stale: '.json_encode($r));
foreach(['client_device_session_id'=>999,'desired_generation'=>6,'assignment_hash'=>h('b'),'desired_leg_set_hash'=>h('9')] as $field=>$value){ $bad=db($legHash); $bad->lifecycle[0][$field]=$value; $r=runCase($bad,$current,$legs,$legHash); if(!in_array('lifecycle_snapshot_missing',$r['blockers']??[],true)) fail('wrong '.$field.' expected missing: '.json_encode($r)); }
foreach(['non_monotonic_runtime_sequence','payload_too_large'] as $code){ $db=db($legHash); $db->rej[]=['scope'=>'global','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'desired_generation'=>5,'assignment_hash'=>h('a'),'platform_family'=>'linux','rejection_code'=>$code,'created_at_unix'=>999]; $r=runCase($db,$current,$legs,$legHash); if(!in_array('snapshot_rejection:'.$code,$r['blockers']??[],true)) fail('scoped rejection '.$code.' should halt: '.json_encode($r)); }
$db=db($legHash); $db->rej[]=['scope'=>'other','forward_id'=>80,'client_id'=>25,'client_device_session_id'=>35,'desired_generation'=>5,'assignment_hash'=>h('a'),'platform_family'=>'linux','rejection_code'=>'payload_too_large','created_at_unix'=>999]; $r=runCase($db,$current,$legs,$legHash); if(!($r['ok']??false)) fail('wrong scope rejection must not halt: '.json_encode($r));
echo "ok\n";
